def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast path: extract opponent and own histories once.
    opp = [h[1] for h in history]

    # Count opponent defections overall and in various windows.
    opp_d = 0
    for x in opp:
        if x == 'D':
            opp_d += 1
    opp_c = n - opp_d

    # Immediate forgiveness: if opponent just cooperated twice, cooperate.
    if n >= 2 and opp[-1] == 'C' and opp[-2] == 'C':
        return 'C'

    # Very early rounds: cooperate to establish mutual cooperation.
    if n < 4:
        return 'C'

    # Track recent opponent behavior.
    look = 8 if n >= 8 else n
    recent_d = 0
    for i in range(n - look, n):
        if opp[i] == 'D':
            recent_d += 1
    recent_c = look - recent_d

    # Endgame: with remaining <= 3, defect unless opponent is a strong cooperator
    # and we risk losing future cooperation (which no longer matters).
    remaining = 100 - n
    if remaining <= 2:
        # If opponent almost never defects, mutual cooperation still gives 3/round;
        # defecting gives 5 this round but may trigger retaliation in remaining rounds.
        if remaining == 1:
            return 'D'
        # remaining == 2: defect if opponent is likely to defect or is not very cooperative
        if opp_c * 10 >= n * 9:
            return 'C'
        return 'D'

    # Detect sustained defector: very high overall defection rate.
    if n >= 12 and opp_d * 4 >= n * 3:
        # Punish, but probe rarely to allow restart.
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # Detect pure defector early.
    if n >= 6 and opp_c == 0:
        return 'D'

    # Detect pure cooperator: exploit at the end, otherwise cooperate mostly.
    if opp_d == 0:
        if n >= 90:
            return 'D'
        return 'C'

    # If opponent has been mostly cooperative overall and recently, cooperate.
    if n >= 8:
        if opp_d * 4 <= n and recent_d <= 1:
            return 'C'

    # Recent defection-heavy opponent: retaliate, with occasional forgiveness.
    if recent_d >= 4:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Moderate recent defections: tit-for-tat with limited forgiveness.
    last_opp = opp[-1]
    if last_opp == 'D':
        # If opponent has been generally cooperative, forgive sometimes.
        if opp_d * 3 <= n:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # Otherwise punish, with small forgiveness chance.
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Opponent just cooperated: cooperate to maintain mutual cooperation.
    return 'C'
